int sum_first_k(int a[], int n, int k) {
    int total = 0;
    for (int i = 0; i < k && i < n; i++) {
        total += a[i];
    }
    return total;
}

int sum_first_k(int a[], int n, int k) {
    int total = 0;
    int i = 0;
    while (i < k && i < n) {
        total = total + a[i];
        i++;
    }
    return total;
}

int sum_first_k(int a[], int n, int k) {
    int total = 0;
    int i;
    int stop = k;
    if (stop > n) {
        stop = n;
    }
    for (i = 0; i < stop; i++) {
        total += a[i];
    }
    return total;
}

